do $$declare p regprocedure;ddl text;begin foreach p in array array['public.submit_missed_punch(date,text,timestamptz,timestamptz,text,uuid)'::regprocedure,'public.get_missed_punches()'::regprocedure,'public.review_missed_punch(uuid,boolean,text)'::regprocedure] loop ddl:=pg_get_functiondef(p);ddl:=replace(ddl,':=private.payroll_actor_id()',':=public.current_hris_user_id()');ddl:=replace(ddl,'if emp is null then','if emp is null or private.payroll_actor_id() is null then');ddl:=replace(ddl,'if actor is null','if private.payroll_actor_id() is null or actor is null');execute ddl;end loop;end $$;notify pgrst,'reload schema';
